-- Fuente: infrastructure/postgres/init/_disabled/04_seed.sql (columnas antiguas
-- nombrekpi/descripcion/direccion_deseada/razon/formula). Remapeado a las
-- columnas REALES de tt_rag.kpi: nombre_kpi, descripcion, categoria, ambito,
