--   nombrekpi        -> nombre_kpi
--   descripcion+razon-> descripcion
--   direccion_deseada-> plegado en ambito ("Dirección deseada: ...")
--   formula          -> formula
--   categoria        -> tema asignado (Académico / Financiero / Investigación /
--                       Experiencia estudiantil / Reputación / Operación)
-- Idempotente: TRUNCATE + RESTART IDENTITY. NO inserta en 'variable'.
-- Datos de demostración; se reemplazarán por los KPIs reales más adelante.
-- ============================================================================
SET search_path TO tt_rag, public;

TRUNCATE tt_rag.kpi RESTART IDENTITY CASCADE;

